from google.cloud import documentai_v1beta2 as documentai

def extract_invoice_data(doc_uri):
    client = documentai.DocumentProcessorServiceClient()
    name = f"projects/{documentai.DEFAULT_PROJECT_ID}/locations/{documentai.DEFAULT_LOCATION_ID}/processors/{documentai.DEFAULT_PROCESSOR_ID}"
    with open(doc_uri, 'rb') as file:
        image = documentai.types.Document(image=documentai.types.Document.Page(image=documentai.types.Document.Page.Image(content=file.read())))
    raw_document = documentai.types.Document(pages=[image])
    request = documentai.types.ProcessDocumentRequest(name=name, raw_document=raw_document)
    result = client.process_document(request=request)
    text = ""
    line_items = []
    for token in result.document.pages[0].tokens:
        text += token.text
        if token.property.role == "line_item":
            line_items.append(token.text)
    invoice_data = {}
    for entity in result.document.entities:
        if entity.display_name == "Vendor":
            invoice_data["Vendor"] = entity.text
        elif entity.display_name == "Date":
            invoice_data["Date"] = entity.text
        elif entity.display_name == "Total":
            invoice_data["Total"] = entity.text
    return invoice_data, line_items
